 import React from 'react'
import { useAuth } from '../contexts/AuthContext'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from '../contexts/TranslationContext'  // Add this
import { 
  LogOut, 
  User, 
  Bell, 
  Shield, 
  Globe, 
  ChevronRight,
  Sun,
  Lock,
  HelpCircle,
  Smartphone,
  ChevronLeft,
  UserCircle
} from 'lucide-react'

export default function Settings() {
    const { user, profile, signOut } = useAuth()
    const { t } = useTranslation()  // Add this
    const navigate = useNavigate()

    const handleSignOut = async () => {
        if (window.confirm('Are you sure you want to sign out?')) {
            await signOut()
            navigate('/login')
        }
    }

    const settingsSections = [
        {
            title: 'Account',
            items: [
                { 
                    icon: UserCircle, 
                    label: t('edit_profile'), 
                    onClick: () => navigate('/profile'),
                    description: profile?.full_name || profile?.username || 'Set up your profile'
                },
                { 
                    icon: Bell, 
                    label: t('notifications'), 
                    onClick: () => navigate('/notifications'),
                    description: 'Manage your notifications'
                },
                { 
                    icon: Lock, 
                    label: t('privacy'), 
                    onClick: () => {},
                    description: 'Control your privacy settings'
                },
            ]
        },
        {
            title: 'Preferences',
            items: [
                { 
                    icon: Sun, 
                    label: t('appearance'), 
                    onClick: () => navigate('/settings/appearance'),
                    description: 'Light / Dark mode'
                },
                { 
                    icon: Globe, 
                    label: t('language'), 
                    onClick: () => navigate('/settings/language'),
                    description: 'Change your language'
                },
            ]
        },
        {
            title: 'Support',
            items: [
                { 
                    icon: HelpCircle, 
                    label: t('help_feedback'), 
                    onClick: () => {},
                    description: 'Get help or send feedback'
                },
                { 
                    icon: Shield, 
                    label: t('privacy_policy'), 
                    onClick: () => {},
                    description: 'Read our privacy policy'
                },
                { 
                    icon: Smartphone, 
                    label: t('app_version'), 
                    onClick: () => {},
                    description: 'v1.0.0'
                },
            ]
        }
    ]

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 px-4 py-6 pb-20 transition-colors duration-200">
            <div className="flex items-center gap-3 mb-6">
                <button 
                    onClick={() => navigate(-1)}
                    className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-lg transition"
                >
                    <ChevronLeft size={24} className="text-gray-700 dark:text-gray-300" />
                </button>
                <h1 className="text-2xl font-bold text-gray-800 dark:text-white">{t('settings')}</h1>
            </div>

            {/* ... rest of your settings component with t() for labels */}
        </div>
    )
}
